$roller = $player;

$roll = EngineRandomInt(1, 6);

$seats = FaBLiveSeats();

$cruSeq1 = $seats;

for ($cruIdx1 = 0; $cruIdx1 < count($cruSeq1); ++$cruIdx1) {

 $seat = $cruSeq1[$cruIdx1];

 $gloves = FaBCRUEquipment($seat, 'gamblers_gloves');

 $cruSeq2 = $gloves;

for ($cruIdx2 = 0; $cruIdx2 < count($cruSeq2); ++$cruIdx2) {

 $glove = $cruSeq2[$cruIdx2];

  $gloveUID = intval(FaBIdentityFromMZ($glove)['object']->UniqueID);

  $tip = 'Player_' . $roller . '_rolled_' . $roll;

  $reroll = await $seat.Modal(1, 1, "Keep_roll&Destroy_gloves_and_reroll", $tip);

  if ($reroll === '1') {
 FaBMoveUID($gloveUID, 'Graveyard', $seat);
 $roll = EngineRandomInt(1, 6);

}


}


}

